const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

const distDir = path.join(__dirname, '../dist/assets');
if (!fs.existsSync(distDir)) {
  console.log('Dist assets directory not found.');
  process.exit(0);
}

const files = fs.readdirSync(distDir);
let totalGzipSize = 0;
let largestChunkSize = 0;
let largestChunkName = '';

files.forEach(file => {
  if (file.endsWith('.js')) {
    const content = fs.readFileSync(path.join(distDir, file));
    const gzipped = zlib.gzipSync(content);
    totalGzipSize += gzipped.length;
    if (gzipped.length > largestChunkSize) {
      largestChunkSize = gzipped.length;
      largestChunkName = file;
    }
  }
});

const totalKb = Math.round(totalGzipSize / 1024);
const largestKb = Math.round(largestChunkSize / 1024);

console.log(`========================================`);
console.log(`PERFORMANCE BUDGET CHECK (GZIPPED)`);
console.log(`========================================`);
console.log(`Total JS Compressed Size: ${totalKb} KB`);
console.log(`Largest Chunk (${largestChunkName}): ${largestKb} KB`);

const TOTAL_BUDGET_KB = 500; // Target is <500 KB total compressed for a rich React app
const CHUNK_BUDGET_KB = 150; // Max chunk size compressed

let failed = false;

if (totalKb > TOTAL_BUDGET_KB) {
  console.error(`❌ ERROR: Total JS compressed size (${totalKb} KB) exceeds budget of ${TOTAL_BUDGET_KB} KB!`);
  failed = true;
} else {
  console.log(`✅ Total JS compressed size is within budget (${TOTAL_BUDGET_KB} KB).`);
}

if (largestKb > CHUNK_BUDGET_KB) {
  console.error(`❌ ERROR: Largest chunk size (${largestKb} KB) exceeds budget of ${CHUNK_BUDGET_KB} KB!`);
  failed = true;
} else {
  console.log(`✅ Largest chunk size is within budget (${CHUNK_BUDGET_KB} KB).`);
}

if (failed) {
  process.exit(1);
} else {
  console.log(`Performance budget check passed.`);
  process.exit(0);
}

import { execSync } from 'child_process';
import fs from 'fs';
import path from 'path';

const dbUrl = (process.env.DATABASE_URL || '').trim();
const hasPostgresUrl = dbUrl.startsWith('postgresql://') || dbUrl.startsWith('postgres://');
const explicitProvider = (process.env.DB_PROVIDER || '').toLowerCase().trim();

// Use PostgreSQL ONLY if a valid postgres URL is present or explicitly configured with valid connection string
const isPostgres = hasPostgresUrl || (explicitProvider === 'postgresql' && hasPostgresUrl);
const rawProvider = isPostgres ? 'postgresql' : 'sqlite';
const schemaPath = isPostgres
  ? 'prisma/schema.postgres.prisma'
  : 'prisma/schema.sqlite.prisma';

console.log(`[PRISMA GENERATE] Selected schema: ${schemaPath} (Provider: ${rawProvider}, NODE_ENV: ${process.env.NODE_ENV || 'development'})`);

try {
  execSync(`npx prisma generate --schema ${schemaPath}`, { stdio: 'inherit' });
} catch (err) {
  console.error('[PRISMA GENERATE] Failed to generate Prisma Client:', err);
  process.exit(1);
}

// Auto-initialize SQLite database and synchronize schema if absent
if (!isPostgres) {
  const dbPath = path.resolve(process.cwd(), 'prisma', 'ruangtenang_sqlite.db');
  if (!fs.existsSync(dbPath)) {
    console.log('[PRISMA INIT] SQLite database not detected. Auto-creating database and synchronizing schema...');
    try {
      execSync('npx prisma db push --schema prisma/schema.sqlite.prisma --skip-generate', { stdio: 'inherit' });
      console.log('[PRISMA INIT] SQLite database schema synchronized successfully.');
    } catch (pushErr) {
      console.error('[PRISMA INIT] Warning: Failed to auto-initialize SQLite schema:', pushErr);
    }
  }
}

const fs = require('fs');
const path = require('path');

function walkDir(dir, callback) {
  fs.readdirSync(dir).forEach(f => {
    const dirPath = path.join(dir, f);
    const isDirectory = fs.statSync(dirPath).isDirectory();
    if (isDirectory) {
      if (f !== 'node_modules' && f !== 'dist' && f !== '.git') {
        walkDir(dirPath, callback);
      }
    } else {
      if (dirPath.endsWith('.ts') || dirPath.endsWith('.tsx')) {
        callback(path.join(dir, f));
      }
    }
  });
}

walkDir(__dirname + '/..', (filePath) => {
  let content = fs.readFileSync(filePath, 'utf8');
  let original = content;
  content = content.replace(/catch \((err|e|error|innerErr|fallbackErr): unknown\)/g, 'catch ($1: any)');
  if (content !== original) {
    fs.writeFileSync(filePath, content, 'utf8');
    console.log('Reverted in', filePath);
  }
});

