async function startServer() {
  const isProd = process.env.NODE_ENV === 'production';

  if (isProd) {
    // In production, secrets and database configuration must be explicitly provided and valid.
    // Auto-generating secrets at runtime in production is prohibited to ensure multi-instance integrity.
    validateEnvironment();
    validateStartupEnvironment();
    await ensureDatabaseReady();
  } else {
    // Local development/test: initialize dev fallbacks if unset
    if (!process.env.JWT_SECRET) {
      process.env.JWT_SECRET = 'local-development-fallback-secret-ruangtenang-key-32';
      console.warn('[DEV NOTICE] Using development JWT_SECRET.');
    }
    const rawEncKey = process.env.DATA_ENCRYPTION_KEY || process.env.ENCRYPTION_KEY;
    if (!rawEncKey) {
      process.env.ENCRYPTION_KEY = 'local-dev-aes-encryption-key-ruangtenang-32-chars-long';
      process.env.DATA_ENCRYPTION_KEY = process.env.ENCRYPTION_KEY;
      console.warn('[DEV NOTICE] Using development ENCRYPTION_KEY.');
    }
    if (!process.env.DATABASE_URL) {
      process.env.DATABASE_URL = 'file:./prisma/ruangtenang_sqlite.db';
    }

    try {
      validateEnvironment();
      validateStartupEnvironment();
    } catch (envErr: any) {
      console.warn('[STARTUP CONFIG] Environment validation notice (dev):', envErr?.message || envErr);
    }

    try {
      await ensureDatabaseReady();
    } catch (dbErr: any) {
      console.warn('[STARTUP DATABASE] Database readiness notice (dev):', dbErr?.message || dbErr);
    }
  }

  const app = express();

  const PORT = 3000;

  // Trust proxy setup for Cloud Run / reverse proxies
  const trustProxySetting = process.env.TRUST_PROXY || '1';
  app.set('trust proxy', trustProxySetting === 'true' ? true : isNaN(Number(trustProxySetting)) ? trustProxySetting : Number(trustProxySetting));

  // CORS Exact Allowlist Setup
  const allowedOrigins = new Set<string>();
  if (process.env.APP_ORIGIN) {
    process.env.APP_ORIGIN.split(',').forEach(o => {
      if (o.trim()) allowedOrigins.add(o.trim().toLowerCase());
    });
  }
  if (process.env.CORS_ALLOWED_ORIGINS) {
    process.env.CORS_ALLOWED_ORIGINS.split(',').forEach(o => {
      if (o.trim()) allowedOrigins.add(o.trim().toLowerCase());
    });
  }

  if (!isProd) {
    allowedOrigins.add('https://ruangtenang.ai.studio');
    allowedOrigins.add('https://ruangtenang.ui.ac.id');
    allowedOrigins.add('http://localhost:3000');
    allowedOrigins.add('http://127.0.0.1:3000');
    allowedOrigins.add('http://localhost:5173');
    allowedOrigins.add('http://127.0.0.1:5173');
  }

  app.use(cors({
    origin: (origin, callback) => {
      // Allow requests without Origin header (e.g. health checks, server-to-server, reverse proxy, static files)
      if (!origin) {
        return callback(null, true);
      }

      const lowerOrigin = origin.toLowerCase();

      // Strict allowlist checking in production
      if (isProd) {
        if (allowedOrigins.has(lowerOrigin)) {
          return callback(null, true);
        }
        return callback(null, false);
      }

      // Development / staging / preview convenience
      const isPlatformDomain = lowerOrigin.endsWith('.run.app') ||
                               lowerOrigin.endsWith('.ai.studio') ||
                               lowerOrigin === 'https://ai.studio' ||
                               lowerOrigin.endsWith('.google.com') ||
                               lowerOrigin.endsWith('.google.dev');

      const isDevAllowed = lowerOrigin.includes('localhost') ||
                           lowerOrigin.includes('127.0.0.1');

      if (isPlatformDomain || isDevAllowed || allowedOrigins.has(lowerOrigin)) {
        return callback(null, true);
      }

      return callback(null, false);
    },
    credentials: true,
  }));

  const trustedOriginsList = [
    ...(process.env.APP_ORIGIN ? process.env.APP_ORIGIN.split(',').map(o => o.trim()).filter(Boolean) : []),
    ...(process.env.CORS_ALLOWED_ORIGINS ? process.env.CORS_ALLOWED_ORIGINS.split(',').map(o => o.trim()).filter(Boolean) : []),
  ];

  // Preview environment detection
  const isPreviewMode = !isProd || process.env.IS_AI_STUDIO_PREVIEW === 'true' || process.env.PREVIEW_MODE === 'true';

  // Frame ancestors (Clickjacking Protection & AI Studio Iframe Preview Support)
  const frameAncestorsList = isPreviewMode
    ? [
        "'self'",
        "https://*.google.com",
        "https://*.google.dev",
        "https://*.run.app",
        "https://*.ai.studio",
        "https://ai.studio",
        "https://aistudio.google.com",
        ...trustedOriginsList
      ]
    : [
        "'self'",
        ...trustedOriginsList
      ];

  const connectSrcList = isPreviewMode
    ? [
        "'self'", 
        "https://generativelanguage.googleapis.com", 
        "https://*.google.com",
        "https://*.google.dev",
        "https://*.run.app", 
        "https://*.ai.studio", 
        "https://ai.studio", 
        "ws:", 
        "wss:",
        "data:",
        ...trustedOriginsList
      ]
    : [
        "'self'",
        "https://generativelanguage.googleapis.com",
        ...trustedOriginsList
      ];

  // In production, Vite bundle runs without eval. Only allow unsafe-eval in development mode if needed.
  const scriptSrcDirectives = isProd
    ? ["'self'", "'unsafe-inline'", "blob:"]
    : ["'self'", "'unsafe-inline'", "'unsafe-eval'", "blob:"];

  app.use(helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        objectSrc: ["'none'"],
        baseUri: ["'self'"],
        scriptSrc: scriptSrcDirectives,
        scriptSrcAttr: ["'none'"],
        styleSrc: ["'self'", "'unsafe-inline'", "https://fonts.googleapis.com"],
        fontSrc: ["'self'", "https://fonts.gstatic.com", "data:"],
        imgSrc: ["'self'", "data:", "blob:", "https://images.unsplash.com", "https://api.dicebear.com", "https://*.google.com", "https://*.googleapis.com", "https://*.googleusercontent.com", "https://*.gstatic.com"],
        connectSrc: connectSrcList,
        frameAncestors: frameAncestorsList,
        workerSrc: ["'self'", "blob:"]
      }
    },
    // Frameguard disabled in favor of granular frameAncestors CSP to permit controlled preview iframe embedding
    frameguard: false,
    crossOriginEmbedderPolicy: isPreviewMode ? false : { policy: "credentialless" },
    crossOriginOpenerPolicy: isPreviewMode ? false : { policy: "same-origin" },
    crossOriginResourcePolicy: isPreviewMode ? false : { policy: "same-origin" },
    hsts: isProd ? { maxAge: 31536000, includeSubDomains: true, preload: true } : false,
  }));

  // Dedicated client telemetry rate limiter (max 30 requests per 15 min window)
  const clientTelemetryLimiter = rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 30,
    standardHeaders: true,
    legacyHeaders: false,
    message: { success: false, error: 'Terlalu banyak laporan telemetry. Silakan tunggu.', code: 'RATE_LIMIT_EXCEEDED' }
  });

  // Apply general API limiter and privacy cache headers
  app.use('/api/', (req, res, next) => {
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
    res.setHeader('Pragma', 'no-cache');
    res.setHeader('Expires', '0');
    res.setHeader('Surrogate-Control', 'no-store');
    next();
  }, generalApiLimiter);

  // 2. Core Middleware Stack
  app.use(compression());
  // Request Body Size Limit: reduced to 256kb for security hardening
  app.use(express.json({ limit: '256kb' }));
  app.use(cookieParser());
  app.use(requestIdAndLoggerMiddleware);
  app.use(timeoutMiddleware(15000));
  app.use(csrfProtection);

  // 3. OpenAPI & Swagger Documentation Protection
  app.get(['/api/v1/openapi.json', '/api/openapi.json'], (_req, res) => {
    if (isProd && process.env.ENABLE_PUBLIC_DOCS !== 'true') {
      return res.status(404).json({ success: false, code: 'NOT_FOUND', error: 'Endpoint tidak ditemukan' });
    }
    res.json(openApiSpec);
  });

  app.get(['/api/v1/docs', '/api/docs', '/docs'], (_req, res) => {
    if (isProd && process.env.ENABLE_PUBLIC_DOCS !== 'true') {
      return res.status(404).send('Not Found');
    }
    res.setHeader('Content-Type', 'text/html');
    res.send(renderSwaggerHtml());
  });

// 4. Liveness & Readiness Endpoints (Sanitized in Production)
  app.get(['/api/v1/health', '/api/health', '/health', '/healthz'], (_req, res) => {
    res.status(200).json({ status: 'healthy' });
  });

  app.get(['/api/v1/readyz', '/readyz'], async (_req, res) => {
    try {
      await serverDb.getAppointments(undefined, 1, 0); // Minimal DB ping
      res.status(200).json({ status: 'ready', database: 'connected' });
    } catch (error) {
      res.status(503).json({ status: 'not_ready', database: 'disconnected' });
    }
  });

  // Redesigned secure asynchronous client telemetry endpoint (Zod validated, PII redacted, no synchronous disk append)
  app.post(['/api/v1/client-debug', '/api/client-debug'], clientTelemetryLimiter, optionalAuth, async (req, res) => {
    const parsed = clientDebugSchema.safeParse(req.body);
    if (!parsed.success) {
      return res.status(400).json({
        success: false,
        error: 'Payload telemetry tidak valid.',
        details: parsed.error.issues.map(e => ({ path: e.path.join('.'), message: e.message })),
        code: 'VALIDATION_ERROR',
        requestId: req.requestId
      });
    }

    const clientIp = (req.headers['x-forwarded-for'] as string) || req.socket.remoteAddress;
    const result = await clientTelemetryService.recordClientError(parsed.data, {
      userId: req.user?.userId,
      requestId: req.requestId || 'req-telemetry',
      clientIp
    });

    res.status(200).json({
      success: true,
      data: result,
      code: 'TELEMETRY_RECORDED',
      requestId: req.requestId
    });
  });

  // Observability & System Operational Metrics (Prometheus / JSON)
  app.get(['/api/v1/metrics', '/metrics'], optionalAuth, (req, res) => {
    const isPrometheus = req.headers.accept?.includes('text/plain');
    if (isPrometheus) {
      res.setHeader('Content-Type', 'text/plain; version=0.0.4; charset=utf-8');
      return res.send(metricsService.toPrometheusText());
    }
    return res.json({
      success: true,
      data: metricsService.getSnapshot(),
      requestId: req.requestId
    });
  });

  app.get(['/api/v1/readiness', '/api/readiness', '/readyz'], async (req, res) => {
    let isHealthy = true;

    try {
      await serverDb.ping();
    } catch (e: any) {
      console.error('[READINESS] Database connection failed:', e.message);
      isHealthy = false;
    }

    if (!process.env.JWT_SECRET) {
       console.error('[READINESS] Critical config JWT_SECRET is missing');
       isHealthy = false;
    }

    // In production without admin token, do not expose detailed service breakdowns or environment names
    if (isProd) {
      return res.status(isHealthy ? 200 : 503).json({
        status: isHealthy ? 'ready' : 'unready'
      });
    }

    // Non-production detailed response
    res.status(isHealthy ? 200 : 503).json({
      status: isHealthy ? 'ready' : 'unready',
      timestamp: new Date().toISOString(),
      services: {
        database: isHealthy ? 'UP' : 'DOWN',
        ai: getAiClient() ? 'UP' : 'DEGRADED'
      },
      environment: process.env.NODE_ENV || 'development'
    });
  });

  app.get(['/api/v1/verify-gemini', '/api/verify-gemini'], diagnosticsLimiter, optionalAuth, async (req, res) => {
    const isProduction = process.env.NODE_ENV === 'production';
    const isDiagnosticsEnabled = process.env.ENABLE_AI_DIAGNOSTICS === 'true';
    const isAuthenticated = Boolean(req.user);
    const isAdminUser = req.user?.role === 'admin';

    // Production: requires ENABLE_AI_DIAGNOSTICS=true AND authenticated admin
    if (isProduction) {
      if (!isDiagnosticsEnabled || !isAuthenticated || !isAdminUser) {
        return res.status(403).json({
          success: false,
          error: 'Akses ditolak. Endpoint diagnostik dinonaktifkan atau memerlukan akses administrator terautentikasi.',
          timestamp: new Date().toISOString()
        });
      }
    } else {
      // Non-production (dev/test): requires ENABLE_AI_DIAGNOSTICS=true OR authenticated admin
      if (!isDiagnosticsEnabled && !isAdminUser) {
        return res.status(403).json({
          success: false,
          error: 'Akses ditolak. Endpoint diagnostik dinonaktifkan demi keamanan.',
          timestamp: new Date().toISOString()
        });
      }
    }

    try {
      const aiClient = getAiClient();

      if (!aiClient) {
        console.error('[GEMINI_VERIFICATION] API Key is missing or GenAI client failed to initialize.');
        return res.status(503).json({
          success: false,
          status: 'error',
          message: 'Layanan AI belum dikonfigurasi atau tidak tersedia.',
          timestamp: new Date().toISOString()
        });
      }

      console.log('[GEMINI_VERIFICATION] Attempting to connect to Gemini API...');
      const startTime = Date.now();

      // Send a minimal ping prompt to verify connectivity
      const response = await aiClient.models.generateContent({
        model: 'gemini-3.1-flash-lite',
        contents: 'Ping! Balas dengan "Pong" saja.',
      });

      const latency = Date.now() - startTime;
      const textResponse = response.text ? 'OK' : 'EMPTY_RESPONSE';

      res.status(200).json({
        success: true,
        status: 'success',
        latencyMs: latency,
        modelUsed: 'gemini-3.1-flash-lite',
        responseStatus: textResponse,
        timestamp: new Date().toISOString()
      });
    } catch (error: any) {
      console.error('[GEMINI_VERIFICATION] Gemini API connection failed (internal log):', error?.message || error);

      res.status(502).json({
        success: false,
        status: 'error',
        message: 'Gagal memverifikasi koneksi layanan AI.',
        timestamp: new Date().toISOString()
      });
    }
  });

  // 5. Mount Modular API Routers
  app.use('/api/v1/auth', authRouter);

  app.use('/api/v1/appointments', appointmentsRouter);

  app.use('/api/v1/screenings', screeningRouter);

  app.use('/api/v1/privacy', privacyRouter);

  app.use('/api/v1', adminRouter);
  app.use('/api', adminRouter);

  app.use('/api/v1', emergencyRouter);
  app.use('/api', emergencyRouter);

  app.use('/api/v1', usabilityRouter);
  app.use('/api', usabilityRouter);

  app.use('/api/v1', counselorChatRouter);
  app.use('/api', counselorChatRouter);

  app.use('/api/v1', chatRouter);
  app.use('/api', chatRouter);

  app.use('/api/v1', userDataRouter);
  app.use('/api', userDataRouter);

  app.use('/api/v1', counselorsRouter);
  app.use('/api', counselorsRouter);

  // 6. Centralized Error Handling
  app.use(centralizedErrorHandler);

  // 7. Vite Integration & Static Assets
  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else {
    // Security filter: Deny direct access to server build artifacts, source maps, prisma schemas, and env files
    app.use((req, res, next) => {
      const normalizedPath = req.path.toLowerCase();
      if (
        normalizedPath.endsWith('.cjs') ||
        normalizedPath.endsWith('.map') ||
        normalizedPath.includes('.env') ||
        normalizedPath.endsWith('.prisma') ||
        normalizedPath.includes('/prisma') ||
        normalizedPath.includes('schema.') ||
        normalizedPath.endsWith('.ts') ||
        normalizedPath.includes('server.') ||
        normalizedPath.includes('database.')
      ) {
        return res.status(404).send('Not Found');
      }
      next();
    });

    const clientDistPath = path.join(process.cwd(), 'dist', 'client');
    const rootDistPath = path.join(process.cwd(), 'dist');
    const staticPath = fs.existsSync(clientDistPath) ? clientDistPath : rootDistPath;

    if (fs.existsSync(staticPath)) {
      app.use(express.static(staticPath, {
        maxAge: '1d',
        dotfiles: 'deny',
        index: 'index.html',
        setHeaders: (res, filePath) => {
          if (filePath.endsWith('.html')) {
            res.setHeader('Cache-Control', 'no-cache');
          } else if (filePath.endsWith('.map') || filePath.endsWith('.cjs')) {
            // Defense in depth
            res.setHeader('Cache-Control', 'no-store');
          } else {
            res.setHeader('Cache-Control', 'public, max-age=31536000, immutable');
          }
        }
      }));

      app.get('*', (_req, res) => {
        const indexPath = path.join(staticPath, 'index.html');
        if (fs.existsSync(indexPath)) {
          res.sendFile(indexPath);
        } else {
          res.status(404).send('Not Found');
        }
      });
    }
  }

  // 8. Background Data Retention Cron Jobs
  try {
    const { initRetentionCronJobs } = await import('./server/jobs/cronRetention.js');
    initRetentionCronJobs();

    // Appointment Reminder Job
    const { startAppointmentReminderJob } = await import('./server/jobs/appointmentReminderJob.js');
    startAppointmentReminderJob();
  } catch(err) {
    console.error('Failed to initialize cron jobs:', err);
  }

  // 9. Fallback Error Handler
  app.use((err: any, _req: express.Request, res: express.Response, _next: express.NextFunction) => {
    console.error('Unhandled Error:', err);
    res.status(500).json({
      success: false,
      code: 'INTERNAL_SERVER_ERROR',
      message: 'Terjadi kesalahan pada server. Silakan coba lagi.'
    });
  });

const server = app.listen(PORT, '0.0.0.0', () => {
    console.log(`Server RuangTenang running on http://0.0.0.0:${PORT}`);
  });

  // Graceful Shutdown
  const shutdown = async (signal: string) => {
    console.log(`
[${signal}] Shutting down gracefully...`);
    server.close(async () => {
      console.log('HTTP server closed.');
      // Add other cleanup here (e.g., Prisma disconnect, Redis quit)
      process.exit(0);
    });

    // Fallback timeout
    setTimeout(() => {
      console.error('Forcing shutdown after 10 seconds...');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));
}

startServer().catch((err) => {
  console.error('FATAL STARTUP ERROR: RuangTenang server failed to initialize:', err?.message || err);
  process.exit(1);
});

import { describe, it, expect } from 'vitest';
import { sanitizeInput } from '../../security.js';
import { scanAndSanitizePII } from '../../services/piiService.js';

describe('Security Utilities', () => {
  describe('stripPII', () => {
    it('should strip email addresses', () => {
      const input = 'My email is budi.santoso@ui.ac.id please contact me';
      const result = scanAndSanitizePII(input).sanitizedText;
      expect(result).toBe('My email is [EMAIL_TERSEMBUNYI] please contact me');
    });

    it('should strip Indonesian phone numbers', () => {
      const input = 'Call me at 081234567890 or +6281234567890.';
      const result = scanAndSanitizePII(input).sanitizedText;
      expect(result).toBe('Call me at [NOMOR_HP_TERSEMBUNYI] or [NOMOR_HP_TERSEMBUNYI].');
    });

    it('should strip NIMs', () => {
      const input = 'My student ID is 1234567890.';
      const result = scanAndSanitizePII(input).sanitizedText;
      expect(result).toBe('My student ID is [NIM_TERSEMBUNYI].');
    });

    it('should strip explicit self-identifying names', () => {
      const input = 'Halo, nama saya Budi Santoso dan saya sedih.';
      const result = scanAndSanitizePII(input).sanitizedText;
      expect(result).toBe('Halo, nama saya [MAHASISWA] dan saya sedih.');
    });

    it('should handle empty or null input', () => {
      expect(scanAndSanitizePII('').sanitizedText).toBe('');
      // @ts-ignore testing invalid input
      expect(scanAndSanitizePII(null).sanitizedText).toBe('');
    });
  });

  describe('sanitizeInput', () => {
    it('should strip HTML tags', () => {
      const input = '<script>alert("xss")</script><p>Hello</p>';
      const result = sanitizeInput(input);
      expect(result).toBe('Hello');
    });

    it('should truncate to max length', () => {
      const input = 'a'.repeat(2000);
      const result = sanitizeInput(input, 1000);
      expect(result.length).toBe(1000);
    });
  });
});

