// Ensure database is ready and initialized
export async function ensureDatabaseReady(): Promise<void> {
  const isProd = process.env.NODE_ENV === 'production';
  const dbUrl = (process.env.DATABASE_URL || '').trim();
  const explicitProvider = (process.env.DB_PROVIDER || '').toLowerCase().trim();
  const hasPostgresUrl = dbUrl.startsWith('postgresql://') || dbUrl.startsWith('postgres://');
  const isPostgres = hasPostgresUrl || (explicitProvider === 'postgresql' && hasPostgresUrl);

  if (isProd && !isPostgres) {
    throw new Error('FATAL DATABASE ERROR: Production requires PostgreSQL. SQLite fallback is strictly prohibited in production.');
  }

  try {
    if (!isPostgres) {
      try {
        const { existsSync, mkdirSync } = await import('fs');
        const { resolve } = await import('path');
        const prismaDir = resolve(process.cwd(), 'prisma');
        if (!existsSync(prismaDir)) {
          mkdirSync(prismaDir, { recursive: true });
        }
      } catch {}

      try {
        await prisma.users.count();
      } catch {
        console.log('[DATABASE INIT] Initializing SQLite database schema...');
        try {
          const { execSync } = await import('child_process');
          execSync('npx prisma db push --schema prisma/schema.sqlite.prisma --skip-generate', { stdio: 'inherit' });
          console.log('[DATABASE INIT] SQLite database schema initialized successfully.');
        } catch (err: any) {
          console.warn('[DATABASE INIT] Note on schema initialization:', err?.message || err);
        }
      }
      await prisma.$queryRaw`SELECT 1`;
      console.log('[DATABASE READY] SQLite database connection verified.');
    } else {
      await prisma.$queryRaw`SELECT 1`;
      console.log('[DATABASE READY] PostgreSQL database connection verified.');
    }
  } catch (outerErr: any) {
    if (isProd) {
      throw new Error(`FATAL DATABASE ERROR: Failed to verify database readiness in production: ${outerErr?.message || outerErr}`);
    }
    console.warn('[DATABASE INIT] Database initialization notice:', outerErr?.message || outerErr);
  }
}

