 */
import { scanAndSanitizePII } from './services/piiService.js';
import { DistributedStateService } from './services/distributedStateService.js';

// Local In-Memory Fast Cache for rate limits
const rateLimitMap = new Map<string, { count: number; resetTime: number }>();

export function checkRateLimit(ip: string, limit: number = 15, windowMs: number = 60000): { allowed: boolean; remaining: number } {
  const now = Date.now();
  const record = rateLimitMap.get(ip);

  if (!record || now > record.resetTime) {
    rateLimitMap.set(ip, { count: 1, resetTime: now + windowMs });
    return { allowed: true, remaining: limit - 1 };
  }

  if (record.count >= limit) {
    return { allowed: false, remaining: 0 };
  }

  record.count += 1;
  return { allowed: true, remaining: limit - record.count };
}

/**
 * Distributed multi-instance safe rate limiter
 */
export async function checkDistributedRateLimit(
  key: string,
  limit: number = 15,
  windowSeconds: number = 60
): Promise<{ allowed: boolean; remaining: number }> {
  const res = await DistributedStateService.checkRateLimit(key, limit, windowSeconds);
  return {
    allowed: res.allowed,
    remaining: res.remaining,
  };
}

/**
 * Sanitizes input string to prevent XSS and excessive payload size.
 */
export function sanitizeInput(text: string, maxLength: number = 1000): string {
  if (!text || typeof text !== 'string') return '';

  // Strip HTML tags
  let clean = text.replace(/<(script|style)[^>]*>[\s\S]*?<\/\1>/gi, '');
  clean = clean.replace(/<[^>]*>?/gm, '');

  // Remove dangerous control characters (except newline, tab, space)
  clean = clean.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '');

  // Trim whitespace and enforce length cap
  clean = clean.trim();
  if (clean.length > maxLength) {
    clean = clean.substring(0, maxLength);
  }

  return clean;
}

/**
 * Detects potential Prompt Injection or Jailbreak attempts.
 */
export function detectPromptInjection(text: string): boolean {
  if (!text) return false;
  const lower = text.toLowerCase();

  const INJECTION_PATTERNS = [
    'ignore previous instructions',
    'ignore all instructions',
    'forget system prompt',
    'forget your rules',
    'dan mode',
    'jailbreak',
    'override instructions',
    'act as a real doctor',
    'pretend you are a licensed psychiatrist',
    'berpura-puralah sebagai dokter',
    'abaikan semua instruksi',
    'lupakan aturan sebelumnya',
    'bypass safety',
    'you are now in developer mode'
  ];

  return INJECTION_PATTERNS.some(pattern => lower.includes(pattern));
}

/**
 * Safe logger that redacts PII before outputting to server stdout.
 */
export function safeLog(message: string, data?: any): void {
  const timestamp = new Date().toISOString();
  const sanitizedMessage = scanAndSanitizePII(message).sanitizedText;
  let dataStr = '';
  if (data) {
    dataStr = typeof data === 'string' 
      ? scanAndSanitizePII(data).sanitizedText 
      : scanAndSanitizePII(JSON.stringify(data)).sanitizedText;
  }
  console.log(`[${timestamp}] ${sanitizedMessage} ${dataStr}`);
}

import { getGenAIClient, isAiAvailable } from '../../config/aiConfig.js';
import { isModelAllowedForTier, getModelInfo, getActualGeminiModel } from './aiModelRegistry.js';

export type ModelTier = 'PRIMARY' | 'FALLBACK' | 'COMPLEX' | 'FAST';

export const aiModelRouter = {
  async executeWithTimeoutAndRetry(
    modelName: string, 
    generateFn: (model: string) => Promise<any>,
    options: { timeoutMs?: number; retries?: number } = {}
  ): Promise<any> {
    const timeoutMs = options.timeoutMs || 15000;
    const maxRetries = options.retries || 2;
    let attempt = 0;
    let lastError: Error | null = null;

    while (attempt <= maxRetries) {
      try {
        const result = await Promise.race([
          generateFn(modelName),
          new Promise((_, reject) => setTimeout(() => reject(new Error('AI_TIMEOUT')), timeoutMs))
        ]);
        return result;
      } catch (err: any) {
        lastError = err;
        attempt++;

        const errMsg = (err.message || String(err)).toLowerCase();
        console.warn(`[AI_MODEL_ROUTER] Attempt ${attempt} failed for ${modelName}: ${err.message || 'Unknown error'}`);

        // Define non-transient error classification
        const isNonTransient = 
          errMsg.includes('safety_block') || 
          errMsg.includes('safety') || 
          errMsg.includes('policy') || 
          errMsg.includes('validation') || 
          errMsg.includes('unauthorized') || 
          errMsg.includes('api_key') || 
          errMsg.includes('invalid') || 
          errMsg.includes('auth') ||
          (err.status && [400, 401, 403, 422].includes(Number(err.status)));

        if (isNonTransient) {
          console.log(`[AI_MODEL_ROUTER] Non-transient failure detected (${err.message || err}). Aborting retry loop immediately.`);
          break;
        }

        if (attempt <= maxRetries) {
          await new Promise(resolve => setTimeout(resolve, attempt * 500));
        }
      }
    }
    throw lastError || new Error('AI execution failed after retries');
  },

  async executeWithFallback(
    requestedModelId: string,
    userTier: string,
    generateFn: (model: string) => Promise<any>,
    options: { timeoutMs?: number; allowFallback?: boolean } = {}
  ): Promise<{ response: any; modelUsed: string }> {
    const aiClient = getGenAIClient();
    if (!aiClient || !isAiAvailable()) {
      throw new Error('AI_UNAVAILABLE');
    }

    let primaryModel = requestedModelId;
    if (!isModelAllowedForTier(requestedModelId, userTier)) {
      console.warn(`[AI_MODEL_ROUTER] Model ${requestedModelId} not allowed for tier ${userTier}. Falling back to default.`);
      primaryModel = 'gemini-3.1-flash-lite';
    }

    const actualPrimary = getActualGeminiModel(primaryModel);

    try {
      const response = await this.executeWithTimeoutAndRetry(actualPrimary, generateFn, { timeoutMs: options.timeoutMs });
      return { response, modelUsed: primaryModel };
    } catch (err: any) {
      if (options.allowFallback === false || err.message === 'SAFETY_BLOCK') {
        throw err;
      }
      console.warn(`[AI_MODEL_ROUTER] Switching to fallback from ${primaryModel}`);
      const fallbackModel = 'gemini-3.1-flash-lite';
      try {
         const response = await this.executeWithTimeoutAndRetry(fallbackModel, generateFn, { timeoutMs: 10000, retries: 1 });
         return { response, modelUsed: fallbackModel };
      } catch (fallbackErr: any) {
         throw new Error(`AI_FALLBACK_FAILED: ${fallbackErr.message || 'Unknown'}`);
      }
    }
  }
};

import { getGenAIClient } from '../../config/aiConfig.js';
import { aiContextBuilder } from './aiContextBuilder.js';
import { aiSafetyService } from './aiSafetyService.js';
import { aiModelRouter } from './aiModelRouter.js';
import { scanAndSanitizePII } from '../piiService.js';
import { getLocalFallbackResponse } from '../../routes/fallbackAi.js';
import { isModelAllowedForTier, getActualGeminiModel } from './aiModelRegistry.js';

export interface AiRequestOptions {
  userId?: string;
  userTier?: string;
  requestedModelId: string;
  prompt: string;
  history?: Array<{ role: 'user' | 'model'; parts: { text: string }[] }>;
  systemInstruction?: string;
}

export const aiRequestService = {
  async generateChatResponse(options: AiRequestOptions): Promise<{ text: string; modelUsed: string; isFallback: boolean }> {
    const { userId, userTier = 'Free', requestedModelId, prompt, history = [], systemInstruction } = options;

    if (aiSafetyService.detectPromptInjection(prompt)) {
      throw new Error('PROMPT_INJECTION_DETECTED');
    }

    const sanitizedPrompt = scanAndSanitizePII(prompt).sanitizedText;
    const sanitizedHistory = history.map(h => ({
      ...h,
      parts: h.parts.map(p => ({
        ...p,
        text: scanAndSanitizePII(p.text).sanitizedText
      }))
    }));

    const crisisCheck = aiSafetyService.detectCrisis(sanitizedPrompt);
    if (crisisCheck.isCrisis) {
      return {
        text: aiSafetyService.getCrisisSafeResponse(),
        modelUsed: 'deterministic-crisis-policy',
        isFallback: true
      };
    }

    const isAnonymous = !userId || userId === 'guest';
    const outputTokens = isAnonymous ? 300 : 800;

    const abortController = new AbortController();
    const timeoutId = setTimeout(() => abortController.abort(), 15000);

    let fullSystemInstruction = systemInstruction || 'Kamu adalah Teman RuangTenang AI, asisten pendamping reflektif mahasiswa yang sangat hangat, ramah, merangkul, dan empati. Berikan tanggapan yang menenangkan dengan bahasa yang hangat serta gunakan emoji (seperti 🌿, 🤍, 🤗, ✨, ☕, 🫂, 🔐) secara alami. Tegaskan bahwa privasi dan keamanan ceritanya dijaga sesuai kebijakan privasi kami, dan kamu mendengarkan tanpa menghakimi. Kamu BUKAN profesional medis, JANGAN melakukan diagnosis medis atau merekomendasikan resep.';

    if (userId && !isAnonymous) {
       const userContext = await aiContextBuilder.buildContext({ userId });
       if (userContext) {
         fullSystemInstruction += `\n\n${userContext}`;
       }
    }

    const aiClient = getGenAIClient();
    if (!aiClient) {
      clearTimeout(timeoutId);
      return {
        text: getLocalFallbackResponse(prompt).text,
        modelUsed: 'local-fallback',
        isFallback: true
      };
    }

    try {
      const { response, modelUsed } = await aiModelRouter.executeWithFallback(requestedModelId, userTier, async (modelName) => {
        return await aiClient.models.generateContent({
           model: modelName,
           contents: [...sanitizedHistory, { role: 'user', parts: [{ text: sanitizedPrompt }] }],
           config: {
             systemInstruction: fullSystemInstruction,
             temperature: 0.6,
             maxOutputTokens: outputTokens,
             // @ts-ignore - The SDK might not explicitly type signal in this version, but native fetch underneath might support it
             signal: abortController.signal
           }
        });
      }, { allowFallback: true });
      clearTimeout(timeoutId);

      const outputText = response.text || '';

      const validation = aiSafetyService.validateOutput(outputText);
      if (!validation.isValid) {
        console.warn(`[AI_REQUEST_SERVICE] Output validation failed: ${validation.reason}`);
        return {
          text: 'Maaf, respons yang saya siapkan tidak dapat ditampilkan karena aturan keamanan. Jika Anda memerlukan bantuan khusus, mohon hubungi profesional medis atau konselor.',
          modelUsed: 'safety-override',
          isFallback: true
        };
      }

      return { text: outputText, modelUsed, isFallback: false };
    } catch (err: any) {
      clearTimeout(timeoutId);
      console.error(`[AI_REQUEST_SERVICE] Final failure: ${err.message}`);
      return {
        text: getLocalFallbackResponse(prompt).text,
        modelUsed: 'local-fallback-after-error',
        isFallback: true
      };
    }
  },

  async generateStreamResponse(options: AiRequestOptions): Promise<{ stream: AsyncGenerator<any, any, unknown>, modelUsed: string }> {
    const { userId, userTier = 'Free', requestedModelId, prompt, history = [], systemInstruction } = options;

    if (aiSafetyService.detectPromptInjection(prompt)) {
      throw new Error('PROMPT_INJECTION_DETECTED');
    }

    const sanitizedPrompt = scanAndSanitizePII(prompt).sanitizedText;

    const sanitizedHistory = history.map(h => ({
      ...h,
      parts: h.parts.map(p => ({
        ...p,
        text: scanAndSanitizePII(p.text).sanitizedText
      }))
    }));

    const crisisCheck = aiSafetyService.detectCrisis(sanitizedPrompt);
    if (crisisCheck.isCrisis) {
      throw new Error('CRISIS_DETECTED');
    }

    const isAnonymous = !userId || userId === 'guest';
    const outputTokens = isAnonymous ? 400 : 1000;

    const abortController = new AbortController();
    const timeoutId = setTimeout(() => abortController.abort(), 60000);

    let fullSystemInstruction = systemInstruction || 'Kamu adalah Teman RuangTenang AI, asisten pendamping reflektif mahasiswa yang sangat hangat, ramah, merangkul, dan empati. Berikan tanggapan yang menenangkan dengan bahasa yang hangat serta gunakan emoji (seperti 🌿, 🤍, 🤗, ✨, ☕, 🫂, 🔐) secara alami. Tegaskan bahwa privasi dan keamanan ceritanya dijaga sesuai kebijakan privasi kami, dan kamu mendengarkan tanpa menghakimi. Kamu BUKAN profesional medis, JANGAN melakukan diagnosis medis atau merekomendasikan resep.';

    if (userId && !isAnonymous) {
       const userContext = await aiContextBuilder.buildContext({ userId });
       if (userContext) {
         fullSystemInstruction += `\n\n${userContext}`;
       }
    }

    const aiClient = getGenAIClient();
    if (!aiClient) {
      clearTimeout(timeoutId);
      throw new Error('AI_UNAVAILABLE');
    }

    let primaryModel = requestedModelId;
    if (!isModelAllowedForTier(requestedModelId, userTier)) {
      primaryModel = 'gemini-3.1-flash-lite';
    }

    const actualPrimary = getActualGeminiModel(primaryModel);

    try {
       const stream = await aiClient.models.generateContentStream({
           model: actualPrimary,
           contents: [...sanitizedHistory, { role: 'user', parts: [{ text: sanitizedPrompt }] }],
           config: {
             systemInstruction: fullSystemInstruction,
             temperature: 0.6,
             maxOutputTokens: outputTokens,
             // @ts-ignore
             signal: abortController.signal
           }
       });
       return { stream, modelUsed: primaryModel };
    } catch (err: any) {
      console.warn(`[AI_REQUEST_SERVICE] Stream primary (${actualPrimary}) failed:`, err?.message || err);
      const fallbackModel = 'gemini-3.1-flash-lite';
      try {
         const stream = await aiClient.models.generateContentStream({
             model: fallbackModel,
             contents: [...sanitizedHistory, { role: 'user', parts: [{ text: sanitizedPrompt }] }],
             config: {
               systemInstruction: fullSystemInstruction,
               temperature: 0.6,
               maxOutputTokens: outputTokens,
               // @ts-ignore
               signal: abortController.signal
             }
         });
         return { stream, modelUsed: fallbackModel };
      } catch (fallbackErr: any) {
         console.error(`[AI_REQUEST_SERVICE] Stream fallback failed:`, fallbackErr?.message || fallbackErr);
         clearTimeout(timeoutId);
         throw new Error('AI_STREAM_FAILED');
      }
    }
  }
};

import twilio from 'twilio';

// Lazy initialization for Twilio credentials
const accountSid = process.env.TWILIO_ACCOUNT_SID;
const authToken = process.env.TWILIO_AUTH_TOKEN;
const twilioPhoneNumber = process.env.TWILIO_PHONE_NUMBER;

let client: twilio.Twilio | null = null;
try {
  if (accountSid && authToken && twilioPhoneNumber) {
    client = twilio(accountSid, authToken);
  }
} catch (error) {
  // Silent catch without dumping credentials
}

export interface SOSPayload {
  studentName?: string;
  emergencyContact: string;
  location?: any;
  crisisSignal: string;
}

export type SOSStatus = 'delivered' | 'failed' | 'not_configured' | 'mock_mode';

function maskPhoneNumber(phone: string): string {
  if (!phone || phone.length < 6) return '****';
  return phone.slice(0, 4) + '****' + phone.slice(-3);
}

export async function sendEmergencySOS(payload: SOSPayload): Promise<{ status: SOSStatus; message: string; error?: string }> {
  try {
    const timeTriggered = new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' });
    const studentInfo = payload.studentName ? `Mahasiswa: ${payload.studentName}` : 'Seorang mahasiswa anonim';

    let locStr = 'Lokasi: Kampus Utama';
    if (payload.location) {
      if (typeof payload.location === 'string') {
        locStr = `Lokasi Terakhir: ${payload.location}`;
      } else if (typeof payload.location === 'object') {
        locStr = `Lokasi Terakhir: ${payload.location.address || 'Diketahui dari GPS'}`;
      }
    }

    const messageBody = `🚨 *DARURAT RUANGTENANG KAMPUS* 🚨\nSinyal SOS telah diaktifkan.\n${studentInfo}\nSinyal Krisis: ${payload.crisisSignal}\nWaktu Pemicuan: ${timeTriggered} WIB\n${locStr}\nSegera hubungi mahasiswa terkait.`;

    const maskedRecipient = maskPhoneNumber(payload.emergencyContact);

    if (client && twilioPhoneNumber) {
      await client.messages.create({
        body: messageBody,
        from: twilioPhoneNumber,
        to: payload.emergencyContact
      });
      console.log(`[SOS GATEWAY] Emergency alert dispatched to ${maskedRecipient}`);
      return { status: 'delivered', message: 'Sinyal darurat berhasil dikirim via SMS/WhatsApp.' };
    }

    if (!accountSid || !authToken) {
      return { status: 'not_configured', message: 'Layanan darurat belum dikonfigurasi oleh admin.' };
    }

    console.log(`[SOS GATEWAY] Local simulation mode to ${maskedRecipient}`);
    return { status: 'mock_mode', message: 'Simulasi pesan darurat dicatat di sistem lokal.' };

  } catch (error: any) {
    console.error('[SOS GATEWAY] Failed to dispatch emergency alert');
    return { status: 'failed', message: 'Gagal mengirim pesan darurat.', error: error.message };
  }
}

export interface SosAlertData {
  userId: string;
  studentName: string;
  triggers: string[];
  action: string;
  timestamp: string;
}

export async function dispatchSosAlert(data: SosAlertData): Promise<{ status: SOSStatus; message: string; error?: string }> {
  const alertMessage = `🚨 DARURAT RUANGTENANG 🚨\n\nMahasiswa: ${data.studentName}\nKondisi Krisis Terdeteksi.\nSistem mendeteksi pola percakapan: ${data.triggers.join(', ')}.\n\nTindakan Rekomendasi: ${data.action}\nWaktu: ${data.timestamp}`;

  if (!client) {
    if (!accountSid || !authToken) {
      return { status: 'not_configured', message: 'Layanan darurat belum dikonfigurasi.' };
    }
    return { status: 'mock_mode', message: 'Simulasi pengiriman otomatis.' };
  }

  try {
    const hotline = process.env.HOTLINE_PHONE_NUMBER;
    if (!hotline) {
      return { status: 'not_configured', message: 'Nomor hotline kampus belum dikonfigurasi.' };
    }
    await client.messages.create({
      body: alertMessage,
      from: twilioPhoneNumber,
      to: hotline,
    });
    return { status: 'delivered', message: 'Peringatan krisis berhasil dikirim ke satgas kampus.' };
  } catch (error: any) {
    return { status: 'failed', message: 'Sinyal SOS gagal dikirim.', error: error.message };
  }
}

export type StreamState = 'idle' | 'connecting' | 'streaming' | 'completed' | 'aborted' | 'failed';

export interface StreamCallbacks {
  onStateChange?: (state: StreamState) => void;
  onMessageStart?: (msgId: string) => void;
  onChunk?: (text: string) => void;
  onPluginSwitch?: (pluginName: string) => void;
  onMessageComplete?: (fullText: string) => void;
  onError?: (error: string) => void;
  onFollowUps?: (followUps: string[]) => void;
  onChatCreated?: (chatId: string) => void;
}

export interface StreamPayload {
  message: string;
  chatId?: string;
  isTemporary?: boolean;
  pluginResult?: string;
  chatMode?: string;
  responseStyle?: string;
  aiModel?: string;
}

export class ChatStreamingClient {
  private activeToken = 0;
  private abortController: AbortController | null = null;
  private state: StreamState = 'idle';

  private changeState(token: number, state: StreamState, callback?: (s: StreamState) => void) {
    if (token !== this.activeToken) return;
    this.state = state;
    if (callback) {
      try {
        callback(state);
      } catch (err) {
        console.warn('Error in onStateChange callback:', err);
      }
    }
  }

  async stream(payload: StreamPayload, callbacks: StreamCallbacks): Promise<void> {
    const token = ++this.activeToken;

    if (this.abortController) {
      try {
        this.abortController.abort();
      } catch (e) {}
    }

    const abortController = new AbortController();
    this.abortController = abortController;
    const assistantMsgId = `msg_${Date.now() + 1}`;
    let currentText = '';
    let pluginName = '';

    this.changeState(token, 'connecting', callbacks.onStateChange);

    try {
      if (token === this.activeToken && callbacks.onMessageStart) {
        callbacks.onMessageStart(assistantMsgId);
      }

      const response = await fetch('/api/v1/chat/stream', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify(payload),
        signal: abortController.signal
      });

      if (token !== this.activeToken) {
        return;
      }

      if (!response.ok) {
        let errorMsg = `HTTP Kesalahan ${response.status}`;
        try {
          const errData = await response.json();
          errorMsg = errData.message || errData.error || errorMsg;
        } catch (e) {}
        throw new Error(errorMsg);
      }

      if (!response.body) throw new Error("No response body");

      this.changeState(token, 'streaming', callbacks.onStateChange);

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';
      let done = false;
      const READ_TIMEOUT_MS = 25000; // 25s read timeout

      const readLoop = async () => {
        while (!done) {
          if (token !== this.activeToken) {
            try { reader.cancel(); } catch (e) {}
            return;
          }

          let timerId: any = null;
          const timeoutPromise = new Promise<never>((_, reject) => {
            timerId = setTimeout(() => reject(new Error('Read timeout')), READ_TIMEOUT_MS);
          });

          try {
            const result = await Promise.race([
              reader.read(),
              timeoutPromise
            ]);

            if (timerId) clearTimeout(timerId);

            if (token !== this.activeToken) {
              try { reader.cancel(); } catch (e) {}
              return;
            }

            const { value, done: readerDone } = result;
            done = readerDone;

            if (value) {
              buffer += decoder.decode(value, { stream: true });
              const lines = buffer.split('\n');
              // Retain incomplete line in buffer
              buffer = lines.pop() || '';

              for (const line of lines) {
                if (token !== this.activeToken) return;

                const trimmed = line.trim();
                if (!trimmed) continue;

                if (trimmed.startsWith('data: ')) {
                  const dataStr = trimmed.substring(6).trim();
                  if (dataStr === '[DONE]') {
                    done = true;
                    break;
                  }
                  try {
                    const parsed = JSON.parse(dataStr);

                    if (parsed.error) {
                      throw new Error(parsed.text || parsed.error || 'Gagal memproses respons');
                    } else if (parsed.tool_call || (parsed.type === 'plugin' && parsed.plugin)) {
                      pluginName = parsed.tool_call || parsed.plugin;
                      if (token === this.activeToken && callbacks.onPluginSwitch) {
                        callbacks.onPluginSwitch(pluginName);
                      }
                    } else if (parsed.text || (parsed.type === 'text' && parsed.content)) {
                      const content = parsed.text || parsed.content;
                      currentText += content;
                      if (token === this.activeToken && callbacks.onChunk) {
                        callbacks.onChunk(content);
                      }
                    } else if (parsed.type === 'followup' && parsed.questions) {
                      if (token === this.activeToken && callbacks.onFollowUps) {
                        callbacks.onFollowUps(parsed.questions);
                      }
                    } else if (parsed.chatId) {
                      if (token === this.activeToken && callbacks.onChatCreated) {
                        callbacks.onChatCreated(parsed.chatId);
                      }
                    }
                  } catch (e: any) {
                    if (e.message !== 'Unexpected end of JSON input' && e.message !== 'Unexpected token' && !e.message.includes('JSON')) {
                      throw e;
                    }
                  }
                }
              }
            }
          } catch (loopErr) {
            if (timerId) clearTimeout(timerId);
            throw loopErr;
          }
        }

        // Flush remaining buffer
        if (token === this.activeToken && buffer.trim()) {
          const trimmed = buffer.trim();
          if (trimmed.startsWith('data: ')) {
            const dataStr = trimmed.substring(6).trim();
            if (dataStr !== '[DONE]') {
              try {
                const parsed = JSON.parse(dataStr);
                if (parsed.text || (parsed.type === 'text' && parsed.content)) {
                  const content = parsed.text || parsed.content;
                  currentText += content;
                  if (token === this.activeToken && callbacks.onChunk) {
                    callbacks.onChunk(content);
                  }
                }
              } catch (e) {}
            }
          }
        }
      };

      await readLoop();

      if (token !== this.activeToken) {
        return;
      }

      this.changeState(token, 'completed', callbacks.onStateChange);

      if (!pluginName && callbacks.onMessageComplete) {
        callbacks.onMessageComplete(currentText);
      }

    } catch (err: any) {
      if (token !== this.activeToken) {
        return;
      }

      if (err.name === 'AbortError' || (err.message && err.message.toLowerCase().includes('abort'))) {
        console.log('Stream aborted by client');
        this.changeState(token, 'aborted', callbacks.onStateChange);
        // Only trigger completion with existing text if there was content streamed
        if (callbacks.onMessageComplete && currentText.trim()) {
          callbacks.onMessageComplete(currentText);
        }
      } else {
        console.error('Streaming client error:', err);
        this.changeState(token, 'failed', callbacks.onStateChange);
        if (callbacks.onError) {
          callbacks.onError(err.message || 'Koneksi terputus.');
        }
      }
    } finally {
      if (this.abortController === abortController) {
        this.abortController = null;
      }
    }
  }

  abort() {
    this.activeToken++;
    if (this.abortController) {
      try {
        this.abortController.abort();
      } catch (e) {}
      this.abortController = null;
    }
    this.state = 'aborted';
  }
}
